"""Contract tests for the final report: summary -> 'Red-Flag Suggestions — Generated by AI' -> clinician review.

Synthetic inputs, software testing only; not clinical evidence.
"""
import os, tempfile
os.environ.setdefault("MEDIKIOSK_DB", os.path.join(tempfile.mkdtemp(), "report.db"))
import pytest
from fastapi.testclient import TestClient
from app.main import app
from app import clinical_report as cr
from app.clinical_nlp import ClinicalNLPService

c = TestClient(app)
H = lambda t: {"Authorization": f"Bearer {t}"}
EMERGENCY = {"cc": "Chest pain", "dur": "Today", "sev": "Severe", "assoc": ["Sweating", "Breathlessness"],
             "pmh": ["Diabetes"], "meds": "metformin 500 mg twice daily", "allergy": "penicillin",
             "free": "Pressure in the centre of my chest since this morning."}
ROUTINE = {"cc": "Joint / back pain", "dur": "1–4 weeks", "sev": "Mild", "progression": "Same",
           "assoc": ["None"], "pmh": ["None"], "meds": "none", "allergy": "none", "fam": ["None"]}


def guest():
    t = c.post("/api/auth/guest?name=Test").json()["token"]
    c.post("/api/consent", json={"purpose": "history_capture", "granted": True}, headers=H(t))
    return t


def doctor_token():
    r = c.post("/api/auth/login", json={"username": os.environ.get("DOCTOR_USER", "doctor"),
                                         "password": os.environ.get("DOCTOR_PASS", "doctor123")})
    assert r.status_code == 200, r.text
    return r.json()["token"]


def report(answers, token=None):
    token = token or guest()
    r = c.post("/api/clinical-summary", json={"answers": answers}, headers=H(token))
    assert r.status_code == 200, r.text
    return r.json()


def test_blocks_are_ordered_summary_then_red_flags_then_review():
    r = report(EMERGENCY)
    assert r["display_order"] == ["clinical_summary", "red_flag_suggestions", "clinician_review"]
    assert list(r.keys()).index("clinical_summary") < list(r.keys()).index("red_flag_suggestions") < list(r.keys()).index("clinician_review")


def test_exact_visible_label_and_notice():
    r = report(EMERGENCY)
    assert r["red_flag_suggestions"]["label"] == "Red-Flag Suggestions \u2014 Generated by AI"
    assert r["red_flag_suggestions"]["notice"] == ("AI-generated decision-support information. Not a confirmed diagnosis. "
                                                    "Review by a qualified healthcare professional is required.")
    assert r["notice"] == r["red_flag_suggestions"]["notice"]


def test_summary_is_draft_unreviewed_with_timestamp_and_no_llm():
    s = report(EMERGENCY)["clinical_summary"]
    assert s["status"] == "DRAFT_UNREVIEWED" and "not reviewed" in s["status_text"].lower()
    assert s["generated_at"].endswith("Z") and s["generator"]["llm_used"] is False
    assert report(EMERGENCY)["clinician_review"]["approved"] is False


def test_emergency_finding_has_every_required_field():
    rf = report(EMERGENCY)["red_flag_suggestions"]
    assert rf["screening_status"] == "complete" and rf["urgency"] == "EMERGENCY"
    item = next(i for i in rf["items"] if i["rule_id"] == "R01")
    assert item["title"] and item["reason"] and item["next_step"] and item["urgency"] == "EMERGENCY"
    assert item["human_review_required"] is True and item["immediate_instruction"]
    assert "pending local clinician sign-off" in item["rule_review_note"]       # provisional wording is disclosed
    assert item["evidence"] and all(e["quote"] and e["source_id"] and e["source_label"] for e in item["evidence"])
    assert "missing_information" in item


def test_no_flag_triggered_message_is_exact_and_not_a_clearance():
    rf = report(ROUTINE)["red_flag_suggestions"]
    assert rf["screening_status"] == "complete" and rf["items"] == []
    assert rf["message"] == "No red-flag rule was triggered by the available information. This does not rule out an emergency."


def test_failed_screening_is_never_displayed_as_no_red_flags(monkeypatch):
    monkeypatch.setattr(ClinicalNLPService, "extract_many", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("down")))
    rf = report(EMERGENCY)["red_flag_suggestions"]
    assert rf["screening_status"] == "unavailable"
    assert rf["message"] == cr.UNAVAILABLE_MESSAGE and "NOT" in rf["message"]
    assert "No red-flag rule was triggered" not in rf["message"]
    assert rf["human_review_required"] is True


def test_failed_screening_escalates_queue_priority_and_flags(monkeypatch):
    monkeypatch.setattr(ClinicalNLPService, "extract_many", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("down")))
    t = guest()
    r = c.post("/api/submit", json={"answers": ROUTINE}, headers=H(t))
    assert r.status_code == 200
    assert r.json()["priority"] == 1
    assert r.json()["red_flags"][0]["code"] == "SCREENING_UNAVAILABLE"


def test_missing_history_is_marked_not_reported_never_negative():
    s = report({"cc": "Fever"})["clinical_summary"]
    status = {m["field"]: m["status"] for m in s["missing_or_uncertain"]["not_collected"]}
    assert status["allergy"] == "Not reported" and status["meds"] == "Not reported"
    assert status["vitals_examination"] == "Not assessed"
    assert not any(f["assertion"] == "absent" for f in s["patient_stated_findings"])


def test_report_omits_empty_sections_instead_of_filling_them_with_boilerplate():
    sections = report({"cc": "Fever"})["clinical_summary"]["sections"]
    by_title = {section["title"]: section for section in sections}
    assert by_title["Chief complaint"]["text"] == "Fever"
    assert "Associated symptoms" not in by_title
    assert "Relevant history" not in by_title
    assert "Current medications and allergies" not in by_title
    assert "Patient's own words" not in by_title


def test_other_complaint_without_free_text_is_not_silently_dropped():
    sections = report({"cc": "Other"})["clinical_summary"]["sections"]
    complaint = next(section for section in sections if section["title"] == "Chief complaint")
    assert complaint["text"] == "Other (details not reported)"


def test_every_stated_finding_is_traceable_to_input_text():
    s = report(EMERGENCY)["clinical_summary"]
    source_text = " ".join(str(v) for v in EMERGENCY.values()).lower()
    assert s["patient_stated_findings"]
    for f in s["patient_stated_findings"]:
        assert f["quote"].lower().strip(" .") in source_text, f


def test_summary_proposes_no_diagnosis_or_treatment():
    blob = str(report(EMERGENCY)["clinical_summary"]["sections"]).lower()
    for banned in ("you have", "diagnosis:", "recommend taking", "prescribe"):
        assert banned not in blob


def test_unauthenticated_and_cross_role_access_blocked():
    assert c.post("/api/clinical-summary", json={"answers": ROUTINE}).status_code == 401
    t = guest()
    assert c.get("/api/doctor/records/1", headers=H(t)).status_code == 403
    assert c.put("/api/doctor/records/1", json={"sections": [], "status": "confirmed"}, headers=H(t)).status_code == 403


def test_submit_persists_report_and_clinician_approval_flips_status_only_on_approve():
    t = guest()
    rid = c.post("/api/submit", json={"answers": EMERGENCY}, headers=H(t)).json()["record_id"]
    d = doctor_token()
    rec = c.get(f"/api/doctor/records/{rid}", headers=H(d)).json()
    assert rec["clinical_report"]["clinical_summary"]["status"] == "DRAFT_UNREVIEWED"
    sections = rec["sections"]
    assert c.put(f"/api/doctor/records/{rid}", json={"sections": sections, "status": "bogus"}, headers=H(d)).status_code == 422
    assert c.put(f"/api/doctor/records/{rid}", json={"sections": sections, "status": "confirmed",
                 "finding_reviews": {"R01": "confirmed"}}, headers=H(d)).status_code == 200
    rec = c.get(f"/api/doctor/records/{rid}", headers=H(d)).json()
    assert rec["clinical_report"]["clinical_summary"]["status"] == "APPROVED_BY_CLINICIAN"
    assert rec["clinical_report"]["clinician_review"]["approved"] is True
    assert rec["clinical_report"]["clinician_review"]["finding_reviews"] == {"R01": "confirmed"}


def test_rejected_review_is_not_labelled_approved():
    t = guest()
    rid = c.post("/api/submit", json={"answers": ROUTINE}, headers=H(t)).json()["record_id"]
    d = doctor_token()
    sections = c.get(f"/api/doctor/records/{rid}", headers=H(d)).json()["sections"]
    c.put(f"/api/doctor/records/{rid}", json={"sections": sections, "status": "rejected"}, headers=H(d))
    cs = c.get(f"/api/doctor/records/{rid}", headers=H(d)).json()["clinical_report"]
    assert cs["clinician_review"]["approved"] is False and cs["clinical_summary"]["status"] == "REJECTED_BY_CLINICIAN"


def test_legacy_summary_endpoint_still_returns_old_keys_plus_report():
    t = guest()
    r = c.post("/api/summary", json={"answers": EMERGENCY}, headers=H(t)).json()
    assert {"sections", "red_flags", "patient_message", "clinical_report"} <= set(r)
